from pathlib import Path
import base64,hashlib,json,subprocess,os,shlex,shutil,datetime
R=Path('/srv/android/asus-apxgpt-clock-source-20261107');R.mkdir();(R/'tmp').mkdir()
K=Path('/srv/android/asus-bmc156-full-kernel-r1/kernel');O=K.parent/'out';src=K/'drivers/clocksource/mtk_timer.c';cfg=O/'.config';cmdfile=O/'drivers/clocksource/.mtk_timer.o.cmd'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
assert sha(src)=='2b298b9f5b7951104340b20b5591c2496746be088d3bec935a69157ba30ca197'
assert sha(cfg)=='10b212cabd28aad012582e86c64695ccd450650b4e09ec8da30c21e094f377c2'
before={str(p):sha(p) for p in [src,cfg,cmdfile]}
new=base64.b64decode('');assert hashlib.sha256(new).hexdigest()=='0c9e26f54ecbbdd8d60c9ed35cbfb62820b6a515ef25d0750fd16c3834db2913'
source=R/'mtk_timer.c';source.write_bytes(new)
line=cmdfile.read_text().splitlines()[0];assert line.startswith('cmd_drivers/clocksource/mtk_timer.o := ')
argv=shlex.split(line.split(' := ',1)[1]);assert argv[0]=='aarch64-linux-gnu-gcc' and argv[-1]==str(src)
assert argv.count('-o')==1 and argv[argv.index('-o')+1]=='drivers/clocksource/.tmp_mtk_timer.o'
argv[argv.index('-o')+1]=str(R/'mtk_timer.o');argv[-1]=str(source)
dep='-Wp,-MD,drivers/clocksource/.mtk_timer.o.d';assert argv.count(dep)==1;argv[argv.index(dep)]='-Wp,-MD,'+str(R/'mtk_timer.o.d')
assert not any(a.startswith(('-save-temps','-fprofile','-fstack-usage')) for a in argv)
env=os.environ.copy();env['TMPDIR']=str(R/'tmp');os.sched_setaffinity(0,{min(os.sched_getaffinity(0))})
p=subprocess.run(argv,cwd=O,env=env,capture_output=True,timeout=120)
(R/'stdout.log').write_bytes(p.stdout);(R/'stderr.log').write_bytes(p.stderr)
after={str(p):sha(p) for p in [src,cfg,cmdfile]};assert before==after
binary=(R/'mtk_timer.o').read_bytes() if p.returncode==0 else b''
assert not binary or binary[:6]==b'\x7fELF\x02\x01'
receipt={'exit':p.returncode,'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'cwd':str(O),'command':argv,'output':str(R/'mtk_timer.o'),'object_bytes':len(binary),'object_sha256':hashlib.sha256(binary).hexdigest() if binary else None,'selected_original_inputs_unchanged':before==after,'source_preimage_sha256':before[str(src)],'source_postimage_sha256':sha(source),'config_sha256':before[str(cfg)],'compiler':str(Path(shutil.which(argv[0])).resolve()),'compiler_version':subprocess.check_output([argv[0],'--version'],text=True).splitlines()[0]}
(R/'receipt.json').write_text(json.dumps(receipt,indent=2)+'\n')
print(json.dumps({'receipt':receipt,'object_b64':base64.b64encode(binary).decode(),'stderr':p.stderr.decode(errors='replace')}))
